using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Diagnostics;using System.Collections.Generic;using System.Threading.Tasks;
sealed partial class WorkspaceWindow {
async Task LifecycleTest(){var checks=new List<string>();Action<string,bool> check=(name,ok)=>{if(!ok)throw new Exception(name);checks.Add(name);};try{timer.Stop();opening=true;Func<string,WorkTab> fake=key=>{var t=new WorkTab{id=Guid.NewGuid().ToString(),studio=key,folder=session,title=key,page=new TabPage(key),panel=new Panel{Dock=DockStyle.Fill},process=Process.GetCurrentProcess()};t.page.Controls.Add(t.panel);items.Add(t);tabs.TabPages.Add(t.page);return t;};var first=fake("music");var second=fake("wobble");opening=false;tabs.SelectedTab=home;BeginPair(first,second);await SelectTab();check("Creating compare while tab selection fires keeps a valid parent",pairSplit.Parent==first.page);tabs.SelectedTab=second.page;await SelectTab();check("Selecting partner moves the pair safely",pairSplit.Parent==second.page);tabs.SelectedTab=home;await SelectTab();check("Home selection retains the hidden pair",compare==second);pairSplit.Parent.Controls.Remove(pairSplit);tabs.SelectedTab=first.page;await SelectTab();check("An temporarily unparented pair can be selected",pairSplit.Parent==first.page);for(int i=0;i<30;i++){EndCompare();BeginPair(first,second);tabs.SelectedTab=second.page;await SelectTab();tabs.SelectedTab=first.page;await SelectTab();}check("Repeated compare creation and focus changes remain stable",pairSplit.Parent==first.page);pairSplit.Parent.Controls.Remove(pairSplit);EndCompare();check("Unparented compare teardown restores both panels",first.panel.Parent==first.page&&second.panel.Parent==second.page);var menu=new ContextMenuStrip();var close=menu.Items.Add("Close tab",null,(a,b)=>{items.Remove(second);tabs.TabPages.Remove(second.page);});DeferMenuDisposal(menu);bool alive=false;menu.Closed+=(a,b)=>alive=!menu.IsDisposed;menu.Show(tabs,new Point(50,20));close.PerformClick();menu.Close();await Task.Delay(100);check("Tab context menu survives its close event then disposes",alive&&menu.IsDisposed);check("Context-menu action removes the intended tab",!items.Contains(second));first.process=null;second.process=null;items.Clear();allowClose=true;Atomic(Path.Combine(WorkspaceProgram.Test,"result.json"),json.Serialize(new{ok=true,checks}));Close();}catch(Exception e){items.Clear();allowClose=true;Atomic(Path.Combine(WorkspaceProgram.Test,"result.json"),json.Serialize(new{ok=false,error=e.ToString(),checks}));Close();}}
}
